def media(xs):
    totale = 0
    for x in xs:
        totale += x
    return totale / len(xs)


def dev_std(xs):
    m = media(xs)
    somma = 0
    for x in xs:
        somma += (x - m) ** 2
    return (somma / (len(xs) - 1)) ** 0.5


def fuori_soglia(xs, k):
    m = media(xs)
    s = dev_std(xs)
    fuori = []
    for x in xs:
        if abs(x - m) > k * s:
            fuori.append(x)
    return fuori
